import { WebPlugin } from '@capacitor/core';
import type { WidgetSyncPlugin, WidgetVerse } from './widget-sync.plugin';

// Web storage keys for simulating widget settings in browser
const WEB_STORAGE_KEY = 'widget_settings';
const WEB_VERSES_KEY = 'widget_verses';

interface WebWidgetSettings {
  selectedTagId: number | null;
  refreshIntervalHours: number;
}

const DEFAULT_REFRESH_INTERVAL_HOURS = 12;

/**
 * Web implementation of WidgetSync plugin.
 * Uses localStorage to persist settings for testing in browser.
 */
export class WidgetSyncWeb extends WebPlugin implements WidgetSyncPlugin {
  private getSettings(): WebWidgetSettings {
    try {
      const stored = localStorage.getItem(WEB_STORAGE_KEY);
      if (stored) {
        return JSON.parse(stored);
      }
    } catch (e) {
      console.warn('[WidgetSync] Error reading settings from localStorage:', e);
    }
    return { selectedTagId: null, refreshIntervalHours: DEFAULT_REFRESH_INTERVAL_HOURS };
  }

  private saveSettings(settings: WebWidgetSettings): void {
    try {
      localStorage.setItem(WEB_STORAGE_KEY, JSON.stringify(settings));
    } catch (e) {
      console.warn('[WidgetSync] Error saving settings to localStorage:', e);
    }
  }

  private getStoredVerses(): WidgetVerse[] {
    try {
      const stored = localStorage.getItem(WEB_VERSES_KEY);
      if (stored) {
        return JSON.parse(stored);
      }
    } catch (e) {
      console.warn('[WidgetSync] Error reading verses from localStorage:', e);
    }
    return [];
  }

  private saveVerses(verses: WidgetVerse[]): void {
    try {
      localStorage.setItem(WEB_VERSES_KEY, JSON.stringify(verses));
    } catch (e) {
      console.warn('[WidgetSync] Error saving verses to localStorage:', e);
    }
  }

  async syncFavorites(options: { verses: WidgetVerse[] }): Promise<void> {
    this.saveVerses(options.verses);
    console.log(
      '[WidgetSync] syncFavorites called on web - stored',
      options.verses.length,
      'verses'
    );
  }

  async setSelectedTag(options: { tagId: number | null }): Promise<void> {
    const settings = this.getSettings();
    settings.selectedTagId = options.tagId;
    this.saveSettings(settings);
    console.log('[WidgetSync] setSelectedTag called on web:', options.tagId);
  }

  async setRefreshInterval(options: { intervalHours: number }): Promise<void> {
    const settings = this.getSettings();
    settings.refreshIntervalHours = options.intervalHours;
    this.saveSettings(settings);
    console.log('[WidgetSync] setRefreshInterval called on web:', options.intervalHours);
  }

  async getWidgetSettings(): Promise<{
    selectedTagId: number | null;
    refreshIntervalHours: number;
  }> {
    const settings = this.getSettings();
    console.log('[WidgetSync] getWidgetSettings called on web:', settings);
    return settings;
  }

  async getSyncedVerses(): Promise<{ verses: WidgetVerse[] }> {
    const allVerses = this.getStoredVerses();
    const settings = this.getSettings();

    // Filter by selected tag if set
    let filteredVerses = allVerses;
    if (settings.selectedTagId !== null) {
      filteredVerses = allVerses.filter((verse) =>
        verse.tags.some((tag) => tag.id === settings.selectedTagId)
      );
    }

    console.log('[WidgetSync] getSyncedVerses called on web:', filteredVerses.length, 'verses');
    return { verses: filteredVerses };
  }

  async reloadWidgets(): Promise<void> {
    // No-op on web
    console.log('[WidgetSync] reloadWidgets called on web (no-op)');
  }
}

